package org.sih.itantra

import org.junit.Assert.assertEquals
import org.junit.Assume.assumeTrue
import org.junit.Test
import org.sih.itantra.domain.model.Language
import org.sih.itantra.ml.translation.IndicTrans2Engine
import java.io.File

/**
 * The Kotlin IndicTrans2 port must reproduce tools/indictrans2_reference.py exactly.
 * Expected strings were generated by that script with onnxruntime 1.20.0 (the version the app
 * uses; other runtime versions can flip near-tied word choices). Skipped when the MT pack isn't downloaded
 * (python tools/download_language_packs.py mt).
 */
class IndicTrans2EngineTest {

    private data class Case(val src: String, val tgt: String, val text: String, val expected: String)

    private val cases = listOf(
        Case("en", "hi", "We need food and water", "हमें भोजन और पानी की आवश्यकता है।"),
        Case("en", "ta", "We need food and water", "எங்களுக்கு உணவு மற்றும் தண்ணீர் தேவை."),
        Case("en", "te", "We need food and water", "మాకు ఆహారం, నీరు కావాలి."),
        Case("en", "kn", "We need food and water", "ನಮಗೆ ಆಹಾರ ಮತ್ತು ನೀರು ಬೇಕು."),
        Case("en", "ml", "We need food and water", "നമുക്ക് ഭക്ഷണവും വെള്ളവും വേണം."),
        Case("en", "bn", "We need food and water", "আমাদের খাদ্য ও জল প্রয়োজন।"),
        Case("en", "mr", "We need food and water", "आम्हाला अन्न आणि पाण्याची गरज आहे."),
        Case("en", "gu", "We need food and water", "આપણને ખોરાક અને પાણીની જરૂર છે."),
        Case("en", "or", "We need food and water", "ଆମକୁ ଖାଦ୍ୟ ଏବଂ ପାଣି ଦରକାର।"),
        Case("en", "pa", "We need food and water", "ਸਾਨੂੰ ਭੋਜਨ ਅਤੇ ਪਾਣੀ ਦੀ ਜ਼ਰੂਰਤ ਹੈ।"),
        Case("en", "hi", "The bridge near the school has collapsed", "स्कूल के पास पुल ढह गया है"),
        Case("en", "ta", "The bridge near the school has collapsed", "பள்ளிக்கு அருகிலுள்ள பாலம் இடிந்து விழுந்தது."),
        Case("en", "te", "The bridge near the school has collapsed", "పాఠశాలకు సమీపంలో వంతెన కూలిపోయింది."),
        Case("en", "kn", "The bridge near the school has collapsed", "ಶಾಲೆಯ ಬಳಿಯ ಸೇತುವೆ ಕುಸಿದಿದೆ."),
        Case("en", "ml", "The bridge near the school has collapsed", "സ്കൂളിനടുത്തുള്ള പാലം തകർന്നു"),
        Case("en", "bn", "The bridge near the school has collapsed", "স্কুলের কাছে সেতুটি ভেঙে পড়েছে।"),
        Case("en", "mr", "The bridge near the school has collapsed", "शाळेजवळचा पूल कोसळला आहे"),
        Case("en", "gu", "The bridge near the school has collapsed", "શાળા નજીકનો પુલ તૂટી પડ્યો છે"),
        Case("en", "or", "The bridge near the school has collapsed", "ବିଦ୍ୟାଳୟ ନିକଟରେ ଥିବା ପୋଲଟି ଭୁଶୁଡ଼ି ପଡ଼ିଛି।"),
        Case("en", "pa", "The bridge near the school has collapsed", "ਸਕੂਲ ਨੇਡ਼ੇ ਦਾ ਪੁਲ ਢਹਿ ਗਿਆ ਹੈ।"),
        Case("ta", "en", "எங்களுக்கு உணவும் தண்ணீரும் தேவை", "We need food and water."),
        Case("hi", "en", "पुल के पास चिकित्सा दल की जरूरत है", "Medical team is needed near the bridge."),
        Case("hi", "ta", "पुल के पास चिकित्सा दल की जरूरत है", "பாலத்திற்கு அருகில் மருத்துவ குழு தேவைப்படுகிறது."),
    )

    private fun mtDir(): File? = listOf(File("../models/packs/mt"), File("models/packs/mt"))
        .firstOrNull { File(it, "en-indic/encoder.onnx").isFile }

    @Test
    fun matchesPythonReference() {
        val dir = mtDir()
        assumeTrue("MT pack not downloaded; skipping", dir != null)
        val engine = IndicTrans2Engine({ dir })
        val mismatches = cases.mapNotNull { c ->
            val out = engine.translate(c.text, Language.fromCode(c.src), Language.fromCode(c.tgt))
            if (out == c.expected) null else "${c.src}>${c.tgt} '${c.text}'\n   expected: ${c.expected}\n   actual:   $out"
        }
        engine.release()
        assertEquals("Kotlin/Python mismatches:\n" + mismatches.joinToString("\n"), 0, mismatches.size)
    }

    @Test
    fun scriptConversionRoundTrips() {
        // Devanagari <-> Telugu offsets are lossless for these letters
        val te = "వంతెన"
        assertEquals(te, IndicTrans2Engine.transliterate(IndicTrans2Engine.transliterate(te, "te", "hi"), "hi", "te"))
    }
}
